// ED-251 (OD-0089): reference frames from the approved composer-lights playground,
// E:/Droppy/work/design/variants/project/ComposerLights.dc.html (generated by work/design/composer-lights/playground/src/gen.py),
// in headless Chrome: the composer on beam-fix/pill.js's neutral card, the light frozen at a time (window.__bbT, __bbTH;
// the aura's clock paused and its phase set). ComposerLightFidelityTests renders the same jobs in the port and compares.
//   node ref.js <out dir> <jobs.json>
// jobs: [{name, th, light: 'beam'|'aura'|'off', beam: {...}, aura: {...}, T, TH, auraP, auraBp, mode}]
const path = require('path'), fs = require('fs');
const { browser, openBoard } = require('E:/Droppy/work/design/composer-lights/beam-fix/lib.js');
const [out, jobsFile] = process.argv.slice(2);
const jobs = JSON.parse(fs.readFileSync(jobsFile, 'utf8'));
const W = 820, H = 52, M = 40;
const BG = { dark: '#171717', light: '#e8e8e8' }, CARD = { dark: '#1c1c1c', light: '#f4f4f4' };
const css = (th) => `
.single .win.big{background:${BG[th]} !important;box-shadow:none !important;border-radius:0 !important}
.single .win.big::before,.single .win.big::after,.single .plate.wbg::before,.single .plate.wbg::after,.single .au-dots.wbg::before,.single .au-dots.wbg::after{display:none !important}
.single .au-dots.wbg{background:${BG[th]} !important}
.single .chat,.single .files,.single .cc{display:none !important}
.single .cmp{left:${M}px !important;top:${M}px !important;bottom:auto !important}
.single .plate{background:${CARD[th]} !important}
.single .obox{left:${M}px !important;top:${M}px !important;bottom:auto !important}
.single .lout{-webkit-mask:none !important;mask:none !important}
`;
(async () => {
  fs.mkdirSync(out, { recursive: true });
  const b = await browser();
  const B = await openBoard(b);
  const stage = await B.page.evaluate(() => { const r = document.querySelector('.single .win.big').getBoundingClientRect(); return { x: r.x, y: r.y }; });
  for (const j of jobs) {
    await B.page.evaluate(([cssText]) => { let s = document.getElementById('pillcss'); if (!s) { s = document.createElement('style'); s.id = 'pillcss'; document.head.appendChild(s); } s.textContent = cssText; }, [css(j.th)]);
    await B.page.evaluate((j) => {
      const c = window.__composerLights;
      window.__bbT = j.T; window.__bbTH = j.TH != null ? j.TH : j.T;
      c.setState({ dark: j.th === 'dark', light: j.light, mode: j.mode || 'rest', auto: false, paused: !!j.pause,
        beam: Object.assign({}, c.state.beam, j.beam || {}), aura: Object.assign({}, c.state.aura, j.aura || {}) });
    }, j);
    await B.page.waitForTimeout(j.wait || 1800);
    if (j.auraP != null) {
      await B.page.evaluate((j) => { const c = window.__composerLights; const k = c.clk[c.singleKey || 'u'] || c.clk.u; k.p = j.auraP; k.bp = j.auraBp || 0; k.amp = j.amp != null ? j.amp : k.amp; }, j);
      await B.page.waitForTimeout(150);
    }
    await B.page.screenshot({ path: path.join(out, j.name + '.png'), clip: { x: stage.x, y: stage.y, width: W + 2 * M, height: H + 2 * M } });
    process.stdout.write('.');
  }
  console.log('\nerrors', B.errors.join(' | ') || 'none');
  await b.close();
})();
